function outer() {
  const outerValue = "Outer";

  function inner() {
    const innerValue = "Inner";

    console.log(innerValue); // Current scope
    console.log(outerValue); // Outer scope
    console.log(globalValue); // Global scope
  }

  inner();
}

outer();

